class MyCLI : public core::CLI {
public:
    MyCLI() {
        _addCommand("greet", "Greets a user by name",
            [](core::CLI* cli, std::vector<std::string> args) {
                if (!args.empty()) {
                    std::cout << GREEN("Hello, " << args[0] << "!\n");
                } else {
                    std::cout << YELLOW("Hello, stranger!\n");
                }
            });
    }
};
